    [Fact]
    [Trait("Category", "Smoke")]
    public async Task RuntimeUnlockFileTransferOwner_MissingPublicationRejectsBeforePathLease()
    {
        FakeNknClient.ResetNetwork();
        var previousHelpeePriorityDelay = NknSignalingTransport.HelperPaidOfferHelpeePriorityDelayOverrideForTests;
        NknSignalingTransport.HelperPaidOfferHelpeePriorityDelayOverrideForTests = TimeSpan.Zero;
        try
        {
            using var cts = new CancellationTokenSource(TimeSpan.FromSeconds(10));
            var options = NknTransportOptions.Load();
            var sidecarPath = Path.Combine(Path.GetTempPath(), "nlink-runtime-unlock-owner-missing.exe");
            var hostClient = new FakeNknClient("host.runtime-unlock.owner-missing.aaaaaaaaaaaaaaaaaaaaaaaa");
            var helperClient = new FakeNknClient("helper.runtime-unlock.owner-missing.bbbbbbbbbbbbbbbbbbbbbbbb");
            var hostLane = new RetryableTunaAccelerationSession(canListen: true, failedDialAttemptsBeforeSuccess: 0);
            using var host = new NknSignalingTransport(
                hostClient,
                options,
                new NknIdentity("host-runtime-unlock-owner-missing-id", hostClient.Address),
                NknTunaAccelerationOptions.CreateRuntimePilot(sidecarPath, NknAccelerationLaneKind.File),
                hostLane);
            using var helper = new NknSignalingTransport(
                helperClient,
                options,
                new NknIdentity("helper-runtime-unlock-owner-missing-id", helperClient.Address),
                NknTunaAccelerationOptions.CreatePassiveDialer(sidecarPath, NknAccelerationLaneKind.File),
                new RetryableTunaAccelerationSession(canListen: false, failedDialAttemptsBeforeSuccess: 0));

            var sessionId = await ApproveNknSessionAsync(
                host,
                helper,
                cts.Token,
                InviteCapabilities.Chat | InviteCapabilities.FileTransfer);
            const string transferId = "transfer_runtime_unlock_owner_missing";
            _ = await host.OpenFileTransferDataSessionAsync(sessionId, transferId, cts.Token);
            var logStart = GetOperationalLogLength();

            InvokePrivateMethod(host, "ScheduleAccelerationNegotiationIfEligible", "runtime_unlock");

            await WaitUntilAsync(
                () => ReadOperationalLogTail(logStart).Contains(
                    "event=runtime_unlock_filetransfer_owner_missing_before_path_lease;",
                    StringComparison.Ordinal),
                TimeSpan.FromSeconds(5));

            var logTail = ReadOperationalLogTail(logStart);
            Assert.Contains("event=runtime_unlock_filetransfer_owner_missing_before_path_lease;", logTail, StringComparison.Ordinal);
            Assert.Contains("event=runtime_unlock_filetransfer_path_lease_rejected_no_current_owner;", logTail, StringComparison.Ordinal);
            Assert.Contains("rejection_reason=missing_current_filetransfer_route_publication_authority", logTail, StringComparison.Ordinal);
            Assert.DoesNotContain("event=tuna_path_lease_started;", logTail, StringComparison.Ordinal);
            Assert.DoesNotContain("event=tuna_acceleration_offer_queued; reason=runtime_unlock;", logTail, StringComparison.Ordinal);
            Assert.False(host.RuntimeUnlockOfferStateForTests.HasOutboundOffer);
        }
        finally
        {
            NknSignalingTransport.HelperPaidOfferHelpeePriorityDelayOverrideForTests = previousHelpeePriorityDelay;
            FakeNknClient.ResetNetwork();
        }
    }

    [Fact]
    [Trait("Category", "Smoke")]
    public async Task RuntimeUnlockFileTransferOwner_CurrentCoordinatorPublicationBindsPathLease()
    {
        FakeNknClient.ResetNetwork();
        try
        {
            using var cts = new CancellationTokenSource(TimeSpan.FromSeconds(8));
            var options = NknTransportOptions.Load();
            var hostClient = new FakeNknClient("host.runtime-unlock.owner-current.aaaaaaaaaaaaaaaaaaaaaaaa");
            var helperClient = new FakeNknClient("helper.runtime-unlock.owner-current.bbbbbbbbbbbbbbbbbbbbbbbb");
            using var host = new NknSignalingTransport(
                hostClient,
                options,
                new NknIdentity("host-runtime-unlock-owner-current-id", hostClient.Address));
            using var helper = new NknSignalingTransport(
                helperClient,
                options,
                new NknIdentity("helper-runtime-unlock-owner-current-id", helperClient.Address));

            var sessionId = await ApproveNknSessionAsync(
                host,
                helper,
                cts.Token,
                InviteCapabilities.Chat | InviteCapabilities.FileTransfer);
            const string transferId = "transfer_runtime_unlock_owner_current";
            using var dataSession = await host.OpenFileTransferDataSessionAsync(sessionId, transferId, cts.Token);
            InvokePrivateMethod(
                host,
                "TrackAuthorizedFileTransferRouteHintForTests",
                transferId,
                FileTransferRouteResolver.RegularNknV4FastToken,
                FileTransferProtocol.ProtocolVersionV4,
                "test_regular_route",
                false,
                "unknown",
                "unknown",
                false,
                0L,
                null,
                0);

            var captureMethod = typeof(NknSignalingTransport).GetMethod(
                "TryCaptureCurrentRuntimeUnlockFileTransferOwnerAuthority",
                BindingFlags.Instance | BindingFlags.NonPublic);
            Assert.NotNull(captureMethod);
            var captureArgs = new object?[] { sessionId, null, null };
            var captured = Assert.IsType<bool>(captureMethod!.Invoke(host, captureArgs));
            var authority = Assert.IsType<FileTransferRoutePublicationAuthority>(captureArgs[1]);

            Assert.True(captured);
            Assert.Equal("accepted", Assert.IsType<string>(captureArgs[2]));
            Assert.Equal(sessionId, authority.SessionId);
            Assert.Equal(transferId, authority.TransferId);
            Assert.Equal(FileTransferDirection.Outbound, authority.Direction);
            Assert.Equal(FileTransferRouteResolver.RegularNknV4FastToken, authority.RouteToken);
            Assert.Equal(FileTransferProtocol.ProtocolVersionV4, authority.ProtocolVersion);

            var logStart = GetOperationalLogLength();
            var logAcceptedMethod = typeof(NknSignalingTransport).GetMethod(
                "LogRuntimeUnlockFileTransferOwnerAcceptedBeforePathLease",
                BindingFlags.Static | BindingFlags.NonPublic);
            Assert.NotNull(logAcceptedMethod);
            logAcceptedMethod!.Invoke(null, new object[] { authority, "runtime_unlock" });
            var lease = InvokePrivateMethod(
                host,
                "StartRuntimeUnlockTunaPathLeaseUnsafe",
                sessionId,
                authority.TransferId,
                1L,
                "runtime_unlock");
            Assert.NotNull(lease);

            var logTail = ReadOperationalLogTail(logStart);
            Assert.Contains("event=runtime_unlock_filetransfer_owner_accepted_before_path_lease;", logTail, StringComparison.Ordinal);
            Assert.Contains($"transfer_id={transferId}", logTail, StringComparison.Ordinal);
            Assert.Contains("route=regular_nkn_v4_fast", logTail, StringComparison.Ordinal);
            Assert.Contains("event=tuna_path_lease_started;", logTail, StringComparison.Ordinal);
            Assert.DoesNotContain("transfer_id=(none)", logTail, StringComparison.Ordinal);

            dataSession.Dispose();
            var contextObserved = InvokePrivateMethod(
                host,
                "IsFileTransferRuntimeUnlockContextObserved",
                sessionId);
            Assert.True(Assert.IsType<bool>(contextObserved));

            var postTerminalCaptureArgs = new object?[] { sessionId, null, null };
            var postTerminalCaptured = Assert.IsType<bool>(captureMethod.Invoke(host, postTerminalCaptureArgs));
            Assert.False(postTerminalCaptured);
            Assert.Equal(
                "missing_current_filetransfer_route_publication_authority",
                Assert.IsType<string>(postTerminalCaptureArgs[2]));
        }
        finally
        {
            FakeNknClient.ResetNetwork();
        }
    }

    [Fact]
    [Trait("Category", "Smoke")]
    public async Task RuntimeUnlockFileTransferOwner_MultipleActiveTransfersRejectAmbiguousAuthority()
    {
        FakeNknClient.ResetNetwork();
        try
        {
            using var cts = new CancellationTokenSource(TimeSpan.FromSeconds(8));
            var options = NknTransportOptions.Load();
            var hostClient = new FakeNknClient("host.runtime-unlock.owner-ambiguous.aaaaaaaaaaaaaaaaaaaaaaaa");
            var helperClient = new FakeNknClient("helper.runtime-unlock.owner-ambiguous.bbbbbbbbbbbbbbbbbbbbbbbb");
            using var host = new NknSignalingTransport(
                hostClient,
                options,
                new NknIdentity("host-runtime-unlock-owner-ambiguous-id", hostClient.Address));
            using var helper = new NknSignalingTransport(
                helperClient,
                options,
                new NknIdentity("helper-runtime-unlock-owner-ambiguous-id", helperClient.Address));

            var sessionId = await ApproveNknSessionAsync(
                host,
                helper,
                cts.Token,
                InviteCapabilities.Chat | InviteCapabilities.FileTransfer);
            using var firstSession = await host.OpenFileTransferDataSessionAsync(
                sessionId,
                "transfer_runtime_unlock_owner_ambiguous_first",
                cts.Token);
            using var secondSession = await host.OpenFileTransferDataSessionAsync(
                sessionId,
                "transfer_runtime_unlock_owner_ambiguous_second",
                cts.Token);
            TrackAuthorizedRegularV4RouteForTests(host, "transfer_runtime_unlock_owner_ambiguous_first");
            TrackAuthorizedRegularV4RouteForTests(host, "transfer_runtime_unlock_owner_ambiguous_second");

            var captureMethod = typeof(NknSignalingTransport).GetMethod(
                "TryCaptureCurrentRuntimeUnlockFileTransferOwnerAuthority",
                BindingFlags.Instance | BindingFlags.NonPublic);
            Assert.NotNull(captureMethod);
            var captureArgs = new object?[] { sessionId, null, null };

            Assert.False(Assert.IsType<bool>(captureMethod!.Invoke(host, captureArgs)));
            Assert.Equal("ambiguous_current_filetransfer_owner_authority", Assert.IsType<string>(captureArgs[2]));
        }
        finally
        {
            FakeNknClient.ResetNetwork();
        }
    }

    [Fact]
    [Trait("Category", "Smoke")]
    public async Task RecoveryStateContract_RuntimeUnlockRetryDispatchesBeforeLivenessTerminalizes()
    {
        FakeNknClient.ResetNetwork();
        var previousHelpeePriorityDelay = NknSignalingTransport.HelperPaidOfferHelpeePriorityDelayOverrideForTests;
        var previousStaleWindow = NknSignalingTransport.RuntimeUnlockRecoveryContractStaleNegotiationWindowOverrideForTests;
        var previousSoftSettleDelay = NknSignalingTransport.RuntimeUnlockRecoverySoftSettleDelayOverrideForTests;
        var previousReceiveRecoveryBlocker = NknSignalingTransport.RuntimeUnlockRegularV4ReceiveRecoveryBlockerOverrideForTests;
        var previousObservedBlocker = NknSignalingTransport.RuntimeUnlockOfferObservedSendBlockerReasonOverrideForTests;
        var previousPressureOverride = NknSignalingTransport.RuntimeUnlockOfferQueueAcceptedPressureOverrideForTests;
        var previousAuthorityDeadline = NknSignalingTransport.RuntimeUnlockRetryAuthorityDeadlineOverrideForTests;
        NknSignalingTransport.HelperPaidOfferHelpeePriorityDelayOverrideForTests = TimeSpan.Zero;
        NknSignalingTransport.RuntimeUnlockRecoveryContractStaleNegotiationWindowOverrideForTests = TimeSpan.Zero;
        NknSignalingTransport.RuntimeUnlockRecoverySoftSettleDelayOverrideForTests = TimeSpan.FromSeconds(20);
        NknSignalingTransport.RuntimeUnlockRegularV4ReceiveRecoveryBlockerOverrideForTests = null;
        NknSignalingTransport.RuntimeUnlockOfferObservedSendBlockerReasonOverrideForTests = null;
        NknSignalingTransport.RuntimeUnlockOfferQueueAcceptedPressureOverrideForTests = null;
        NknSignalingTransport.RuntimeUnlockRetryAuthorityDeadlineOverrideForTests = null;
        try
        {
            using var cts = new CancellationTokenSource(TimeSpan.FromSeconds(20));
            var options = NknTransportOptions.Load();
            var tunaSidecarPath = Path.Combine(Path.GetTempPath(), "nlink-recovery-contract-runtime-unlock.exe");
            var hostTunaOptions = NknTunaAccelerationOptions.CreateRuntimePilot(
                tunaSidecarPath,
                NknAccelerationLaneKind.File);
            var helperTunaOptions = NknTunaAccelerationOptions.CreatePassiveDialer(
                tunaSidecarPath,
                NknAccelerationLaneKind.File);
            var hostClient = new FakeNknClient("host.recovery.contract.runtime-unlock.aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa");
            var helperClient = new FakeNknClient("helper.recovery.contract.runtime-unlock.bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb");
            var hostLane = new RetryableTunaAccelerationSession(canListen: false, failedDialAttemptsBeforeSuccess: 0);
            var helperLane = new RetryableTunaAccelerationSession(canListen: false, failedDialAttemptsBeforeSuccess: 0);
            using var host = new NknSignalingTransport(
                hostClient,
                options,
                new NknIdentity("host-recovery-contract-runtime-unlock-id", hostClient.Address),
                hostTunaOptions,
                hostLane);
            using var helper = new NknSignalingTransport(
                helperClient,
                options,
                new NknIdentity("helper-recovery-contract-runtime-unlock-id", helperClient.Address),
                helperTunaOptions,
                helperLane);

            var sessionId = await ApproveNknSessionAsync(
                host,
                helper,
                cts.Token,
                InviteCapabilities.Chat | InviteCapabilities.FileTransfer);
            const string transferId = "transfer_recovery_contract_runtime_unlock";
            _ = await host.OpenFileTransferDataSessionAsync(sessionId, transferId, cts.Token);
            host.SeedSessionLivenessProofForTests(sessionId, DateTimeOffset.UtcNow.ToUnixTimeMilliseconds());
            InvokePrivateMethod(
                host,
                "TrackAuthorizedFileTransferRouteHintForTests",
                transferId,
                FileTransferRouteResolver.RegularNknV4FastToken,
                FileTransferProtocol.ProtocolVersionV4,
                "test_regular_route");
            var recoveryRequest = new FileTransferReceiveRecoveryRequest(
                sessionId,
                transferId,
                FileTransferDirection.Outbound,
                "session_liveness_timeout_pending")
            {
                RouteToken = FileTransferRouteResolver.RegularNknV4FastToken,
                ProtocolVersion = FileTransferProtocol.ProtocolVersionV4,
                LiveRouteEpoch = 0,
                AuthorityReason = "regular_v4_startup_local_only_no_ack",
            };
            InvokePrivateMethod(
                host,
                "MarkFileTransferRegularV4RecoveryLivenessStarted",
                recoveryRequest,
                sessionId,
                transferId,
                "session_liveness_timeout_pending");
            InvokePrivateMethod(
                host,
                "MarkFileTransferRegularV4RecoveryLivenessReceiveProofReceived",
                sessionId,
                transferId,
                "file_transfer_data_frame",
                "control");
            InvokePrivateMethod(
                host,
                "MarkFileTransferRegularV4RecoveryLivenessReceiveProofReceived",
                sessionId,
                transferId,
                "file_transfer_data_frame",
                "control");

            var logStart = GetOperationalLogLength();
            InvokePrivateMethod(host, "MarkFileTransferTunaActivationBridgeRecoveryStarted", "runtime_unlock_offer_send_not_observed");
            InvokePrivateMethod(
                host,
                "ArmRuntimeUnlockRetryAfterRecovery",
                7L,
                sessionId,
                "runtime_unlock_offer_send_not_observed",
                "tuna_activation_offer_send_timeout");
            await WaitUntilAsync(
                () => ReadOperationalLogTail(logStart).Contains("event=session_recovery_contract_started;", StringComparison.Ordinal),
                TimeSpan.FromSeconds(8));

            SetPrivateField(host, "accelerationNegotiationScheduled", 1);
            InvokePrivateMethod(host, "MarkFileTransferTunaActivationBridgeRecoverySettled", "test_recovery_settled");
            hostLane.SetCanListen(true);
            InvokePrivateMethod(host, "ScheduleAccelerationNegotiationIfEligible", "runtime_unlock");

            await WaitUntilAsync(
                () =>
                {
                    var tail = ReadOperationalLogTail(logStart);
                    return tail.Contains("event=runtime_unlock_retry_dispatch_held_by_active_negotiation;", StringComparison.Ordinal);
                },
                TimeSpan.FromSeconds(15));

            var contractProvider = Assert.IsAssignableFrom<ISessionRecoveryStateContract>(host);
            if (contractProvider.TryGetActiveSessionRecoveryContract(sessionId, out var snapshot))
            {
                Assert.Equal(SessionRecoveryContractKind.RuntimeUnlockActivation, snapshot.Kind);
                Assert.True(snapshot.RetryRequired);
                Assert.True(snapshot.QueuedBehindActiveNegotiation);
                Assert.False(snapshot.RetryAuthorityGranted);
                Assert.False(snapshot.RetryObserved);
            }

            var logTail = ReadOperationalLogTail(logStart);
            var positiveLogTail = logTail + Environment.NewLine + LocalOperationalLog.GetRecentLogText();
            Assert.Contains("event=runtime_unlock_retry_dispatch_held_by_active_negotiation;", positiveLogTail, StringComparison.Ordinal);
            Assert.DoesNotContain("event=session_liveness_timeout;", logTail, StringComparison.Ordinal);
        }
        finally
        {
            NknSignalingTransport.HelperPaidOfferHelpeePriorityDelayOverrideForTests = previousHelpeePriorityDelay;
            NknSignalingTransport.RuntimeUnlockRecoveryContractStaleNegotiationWindowOverrideForTests = previousStaleWindow;
            NknSignalingTransport.RuntimeUnlockRecoverySoftSettleDelayOverrideForTests = previousSoftSettleDelay;
            NknSignalingTransport.RuntimeUnlockRegularV4ReceiveRecoveryBlockerOverrideForTests = previousReceiveRecoveryBlocker;
            NknSignalingTransport.RuntimeUnlockOfferObservedSendBlockerReasonOverrideForTests = previousObservedBlocker;
            NknSignalingTransport.RuntimeUnlockOfferQueueAcceptedPressureOverrideForTests = previousPressureOverride;
            NknSignalingTransport.RuntimeUnlockRetryAuthorityDeadlineOverrideForTests = previousAuthorityDeadline;
            FakeNknClient.ResetNetwork();
        }
    }

    [Fact(Skip = "Obsolete: Phase 1 requires coordinator retry authority before this legacy bulk-only probe path; current missing-proof rejection is covered by retry-authority and receive-stall contract tests.")]
    [Trait("Category", "Smoke")]
    public async Task RecoveryStateContract_RuntimeUnlockAuthorityRejectsBulkEndpointWithoutRecentPeerProof()
    {
        FakeNknClient.ResetNetwork();
        var previousHelpeePriorityDelay = NknSignalingTransport.HelperPaidOfferHelpeePriorityDelayOverrideForTests;
        var previousSoftSettleDelay = NknSignalingTransport.RuntimeUnlockRecoverySoftSettleDelayOverrideForTests;
        var previousOfferAnswerTimeout = NknSignalingTransport.AccelerationOfferAnswerTimeoutOverrideForTests;
        var previousBulkBypassWait = NknSignalingTransport.AccelerationControlBulkBypassWaitOverrideForTests;
        var previousPeerProofFreshness = NknSignalingTransport.RuntimeUnlockRetryAuthorityPeerProofFreshnessOverrideForTests;
        NknSignalingTransport.HelperPaidOfferHelpeePriorityDelayOverrideForTests = TimeSpan.Zero;
        NknSignalingTransport.RuntimeUnlockRecoverySoftSettleDelayOverrideForTests = TimeSpan.FromSeconds(20);
        NknSignalingTransport.AccelerationOfferAnswerTimeoutOverrideForTests = TimeSpan.FromMilliseconds(150);
        NknSignalingTransport.AccelerationControlBulkBypassWaitOverrideForTests = TimeSpan.FromMilliseconds(500);
        NknSignalingTransport.RuntimeUnlockRetryAuthorityPeerProofFreshnessOverrideForTests = TimeSpan.FromMilliseconds(-1);
        var blockedControlOffer = new TaskCompletionSource<object?>(TaskCreationOptions.RunContinuationsAsynchronously);
        try
        {
            using var cts = new CancellationTokenSource(TimeSpan.FromSeconds(15));
            var options = NknTransportOptions.Load();
            var hostClient = new FakeNknClient("host.recovery.authority.peer-proof.aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa");
            var helperClient = new FakeNknClient("helper.recovery.authority.peer-proof.bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb");
            hostClient.BeforeSendCoreAsync = async (destination, payload, channel, ct) =>
            {
                if (channel == NknBridgeChannel.Control &&
                    string.Equals(destination, helperClient.ConnectedAddress, StringComparison.Ordinal) &&
                    EnvelopeCodec.TryDeserialize(payload, out var envelope) &&
                    envelope.Type == MsgType.TransportAccelerationOffer)
                {
                    await blockedControlOffer.Task.WaitAsync(ct).ConfigureAwait(false);
                }
            };
            var hostLane = new RetryableTunaAccelerationSession(canListen: false, failedDialAttemptsBeforeSuccess: 0);
            var helperLane = new RetryableTunaAccelerationSession(canListen: false, failedDialAttemptsBeforeSuccess: 0);
            using var host = new NknSignalingTransport(
                hostClient,
                options,
                new NknIdentity("host-recovery-authority-peer-proof-id", hostClient.Address),
                NknTunaAccelerationOptions.Disabled,
                hostLane);
            using var helper = new NknSignalingTransport(
                helperClient,
                options,
                new NknIdentity("helper-recovery-authority-peer-proof-id", helperClient.Address),
                NknTunaAccelerationOptions.Disabled,
                helperLane);

            var sessionId = await ApproveNknSessionAsync(
                host,
                helper,
                cts.Token,
                InviteCapabilities.Chat | InviteCapabilities.FileTransfer);
            const string transferId = "transfer_recovery_authority_peer_proof";
            _ = await host.OpenFileTransferDataSessionAsync(sessionId, transferId, cts.Token);
            SetPrivateField(host, "remoteBulkEndpoint", helperClient.ConnectedBulkAddress);
            InvokePrivateMethod(
                host,
                "TrackAuthorizedFileTransferRouteHintForTests",
                transferId,
                FileTransferRouteResolver.RegularNknV4FastToken,
                FileTransferProtocol.ProtocolVersionV4,
                "test_regular_route",
                false,
                "unknown",
                "unknown",
                false,
                0L,
                null,
                0);

            var logStart = GetOperationalLogLength();
            InvokePrivateMethod(host, "MarkFileTransferTunaActivationBridgeRecoveryStarted", "runtime_unlock_offer_send_not_observed");
            InvokePrivateMethod(
                host,
                "ArmRuntimeUnlockRetryAfterRecovery",
                11L,
                sessionId,
                "runtime_unlock_offer_send_not_observed",
                "tuna_activation_offer_send_timeout");
            InvokePrivateMethod(host, "MarkFileTransferTunaActivationBridgeRecoverySettled", "test_recovery_settled");
            hostLane.SetCanListen(true);
            InvokePrivateMethod(host, "ScheduleAccelerationNegotiationIfEligible", "runtime_unlock");

            await WaitUntilAsync(
                () =>
                {
                    var tail = ReadOperationalLogTail(logStart);
                    return tail.Contains("event=runtime_unlock_regular_v4_peer_visible_window_delivery_failed;", StringComparison.Ordinal) ||
                           tail.Contains("event=runtime_unlock_regular_v4_activation_window_failed;", StringComparison.Ordinal) ||
                           tail.Contains("event=tuna_acceleration_offer_rejected; reason=runtime_unlock;", StringComparison.Ordinal) ||
                           tail.Contains("event=tuna_acceleration_offer_rejected; reason=runtime_unlock_offer_send_not_observed;", StringComparison.Ordinal) ||
                           tail.Contains("event=session_recovery_contract_failed;", StringComparison.Ordinal);
                },
                TimeSpan.FromSeconds(5));
            var logTail = ReadOperationalLogTail(logStart);
            var positiveLogTail = logTail + Environment.NewLine + LocalOperationalLog.GetRecentLogText();
            Assert.Contains(
                "event=tuna_acceleration_control_send_preferred_bulk_observed_lane_selected; purpose=offer",
                positiveLogTail,
                StringComparison.Ordinal);
            Assert.True(
                positiveLogTail.Contains("observed_lane=control_to_bulk_endpoint", StringComparison.Ordinal) ||
                positiveLogTail.Contains("observed_lane=bulk_queue_fallback", StringComparison.Ordinal),
                positiveLogTail);
            Assert.True(
                positiveLogTail.Contains("event=runtime_unlock_regular_v4_peer_visible_window_delivery_failed;", StringComparison.Ordinal) ||
                positiveLogTail.Contains("event=runtime_unlock_regular_v4_activation_window_failed;", StringComparison.Ordinal) ||
                positiveLogTail.Contains("event=tuna_acceleration_offer_rejected; reason=runtime_unlock;", StringComparison.Ordinal) ||
                positiveLogTail.Contains("event=tuna_acceleration_offer_rejected; reason=runtime_unlock_offer_send_not_observed;", StringComparison.Ordinal) ||
                positiveLogTail.Contains("event=session_recovery_contract_failed;", StringComparison.Ordinal),
                positiveLogTail);
            Assert.DoesNotContain("queue_local_only=1", logTail, StringComparison.Ordinal);
        }
        finally
        {
            blockedControlOffer.TrySetResult(null);
            NknSignalingTransport.HelperPaidOfferHelpeePriorityDelayOverrideForTests = previousHelpeePriorityDelay;
            NknSignalingTransport.RuntimeUnlockRecoverySoftSettleDelayOverrideForTests = previousSoftSettleDelay;
            NknSignalingTransport.AccelerationOfferAnswerTimeoutOverrideForTests = previousOfferAnswerTimeout;
            NknSignalingTransport.AccelerationControlBulkBypassWaitOverrideForTests = previousBulkBypassWait;
            NknSignalingTransport.RuntimeUnlockRetryAuthorityPeerProofFreshnessOverrideForTests = previousPeerProofFreshness;
            FakeNknClient.ResetNetwork();
        }
    }

    [Fact]
    [Trait("Category", "Smoke")]
    public async Task RecoveryStateContract_RuntimeUnlockAuthorityUsesControlPlaneWhenObservedLanesTimeout()
    {
        FakeNknClient.ResetNetwork();
