                transferId,
                "session_liveness_timeout_pending");
            InvokePrivateMethod(
                transport,
                "MarkFileTransferRegularV4RecoveryLivenessBridgeRecoveryLifecycle",
                "started",
                "session_liveness_timeout_pending");
            InvokePrivateMethod(
                transport,
                "MarkFileTransferRegularV4RecoveryLivenessBridgeRecoveryLifecycle",
                "completed",
                "test_regular_v4_recovery_completed_without_receive_proof");
