    [Fact]
    public async Task RuntimeUnlockRetryBlockedByRegularV4Recovery_HoldsAcceptedFrontierSettlementUntilLifecycleBoundary()
    {
        FakeNknClient.ResetNetwork();
        var previousHelpeePriorityDelay = NknSignalingTransport.HelperPaidOfferHelpeePriorityDelayOverrideForTests;
        var previousSoftSettleDelay = NknSignalingTransport.RuntimeUnlockRecoverySoftSettleDelayOverrideForTests;
        var previousReceiveRecoveryBlocker = NknSignalingTransport.RuntimeUnlockRegularV4ReceiveRecoveryBlockerOverrideForTests;
        var previousObservedSendBlocker = NknSignalingTransport.RuntimeUnlockOfferObservedSendBlockerReasonOverrideForTests;
        var previousPeerProofFreshness = NknSignalingTransport.RuntimeUnlockRetryAuthorityPeerProofFreshnessOverrideForTests;
        var previousBulkProofBlocker = NknSignalingTransport.RuntimeUnlockBulkQueueObservedProofBlockerOverrideForTests;
        var previousDirectObservedLaneBlocker = NknSignalingTransport.RuntimeUnlockOfferDirectObservedLaneBlockerOverrideForTests;
        var previousPeerVisibleCopyTimeout = NknSignalingTransport.RuntimeUnlockPeerVisibleLifecycleCopyTimeoutOverrideForTests;
        NknSignalingTransport.HelperPaidOfferHelpeePriorityDelayOverrideForTests = TimeSpan.Zero;
        NknSignalingTransport.RuntimeUnlockRecoverySoftSettleDelayOverrideForTests = TimeSpan.Zero;
        NknSignalingTransport.RuntimeUnlockRegularV4ReceiveRecoveryBlockerOverrideForTests = null;
        NknSignalingTransport.RuntimeUnlockOfferObservedSendBlockerReasonOverrideForTests = null;
        NknSignalingTransport.RuntimeUnlockRetryAuthorityPeerProofFreshnessOverrideForTests = null;
        NknSignalingTransport.RuntimeUnlockBulkQueueObservedProofBlockerOverrideForTests = null;
        NknSignalingTransport.RuntimeUnlockOfferDirectObservedLaneBlockerOverrideForTests = null;
        NknSignalingTransport.RuntimeUnlockPeerVisibleLifecycleCopyTimeoutOverrideForTests = null;
        try
        {
            using var cts = new CancellationTokenSource(TimeSpan.FromSeconds(8));
            var options = NknTransportOptions.Load();
            var hostClient = new FakeNknClient("host.runtime-unlock-regular-v4-frontier-settlement.address");
            var helperClient = new FakeNknClient("helper.runtime-unlock-regular-v4-frontier-settlement.address");
            var hostLane = new RetryableTunaAccelerationSession(canListen: true, failedDialAttemptsBeforeSuccess: 0);
            using var host = new NknSignalingTransport(
                hostClient,
                options,
                new NknIdentity("host-runtime-unlock-regular-v4-frontier-settlement-id", hostClient.Address),
                NknTunaAccelerationOptions.Disabled,
                hostLane);
            using var helper = new NknSignalingTransport(
                helperClient,
                options,
                new NknIdentity("helper-runtime-unlock-regular-v4-frontier-settlement-id", helperClient.Address));

            var sessionId = await ApproveNknSessionAsync(
                host,
                helper,
                cts.Token,
                InviteCapabilities.Chat | InviteCapabilities.FileTransfer | InviteCapabilities.ScreenShare);
            const string transferId = "transfer_runtime_unlock_regular_v4_frontier_settlement";
            var coordinatorStatus = RuntimeUnlockRetryDispatchDecisionStatus.Held;
            var authorityRequestCount = 0;
            InstallRuntimeUnlockRetryDispatchCoordinatorForTests(
                host,
                _ =>
                {
                    Interlocked.Increment(ref authorityRequestCount);
                    return coordinatorStatus;
                });
            _ = await host.OpenFileTransferDataSessionAsync(sessionId, transferId, cts.Token);
            InvokePrivateMethod(
                host,
                "TrackAuthorizedFileTransferRouteHintForTests",
                transferId,
                FileTransferRouteResolver.RegularNknV4FastToken,
                FileTransferProtocol.ProtocolVersionV4,
                "test_regular_route",
                false,
                "unknown",
                "unknown",
                false,
                0L,
                null,
                1);
            var recoveryRequest = new FileTransferReceiveRecoveryRequest(
                sessionId,
                transferId,
                FileTransferDirection.Outbound,
                "session_liveness_timeout_pending")
            {
                RouteToken = FileTransferRouteResolver.RegularNknV4FastToken,
                ProtocolVersion = FileTransferProtocol.ProtocolVersionV4,
                LiveRouteEpoch = 1,
                TransferLegGeneration = 1,
                BridgeRecoveryGeneration = 0,
                TransportEpoch = 0,
                AuthorityReason = "regular_v4_startup_local_only_no_ack",
            };
            InvokePrivateMethod(
                host,
                "MarkFileTransferRegularV4RecoveryLivenessStarted",
                recoveryRequest,
                sessionId,
                transferId,
                "session_liveness_timeout_pending");
            InvokePrivateMethod(host, "MarkFileTransferTunaActivationBridgeRecoveryStarted", "session_liveness_timeout_pending");

            SetPrivateField(host, "accelerationNegotiationRetryAttempts", 0);
            var logStart = GetOperationalLogLength();
            InvokePrivateMethod(
                host,
                "ArmRuntimeUnlockRetryAfterRecovery",
                321L,
                sessionId,
                "runtime_unlock_offer_send_not_observed",
                "session_liveness_timeout_pending");
            InvokePrivateMethod(host, "MarkFileTransferTunaActivationBridgeRecoverySettled", "test_recovery_settled");

            await WaitUntilAsync(
                () =>
                {
                    var tail = ReadOperationalLogTail(logStart);
                    return tail.Contains("event=runtime_unlock_retry_blocked_by_regular_v4_receive_recovery;", StringComparison.Ordinal) &&
                           tail.Contains("regular_v4_liveness_generation=1", StringComparison.Ordinal);
                },
                TimeSpan.FromSeconds(3));

            var settlement = new FileTransferRegularV4FrontierRepairSettlement(
                sessionId,
                transferId,
                FileTransferDirection.Outbound,
                FileTransferRouteResolver.RegularNknV4FastToken,
                FileTransferProtocol.ProtocolVersionV4,
                1,
                1,
                0,
                1,
                0,
                0,
                1,
                1,
                null,
                "regular_v4_peer_silence_safety_replay:0:0:64:1",
                0,
                -1,
                64,
                1,
                "repair_dispatch_not_observed",
                FileTransferRegularV4FrontierRepairSettlementOutcome.MissingDispatch,
                FileTransferTransportKind.RegularNkn);
            coordinatorStatus = RuntimeUnlockRetryDispatchDecisionStatus.Rejected;
            InvokePrivateMethod(host, "HandleAcceptedRegularV4FrontierRepairSettlement", settlement);

            var heldTail = ReadOperationalLogTail(logStart);
            Assert.Contains("event=runtime_unlock_regular_v4_frontier_repair_settlement_handoff_adopted;", heldTail, StringComparison.Ordinal);
            Assert.Contains("event=runtime_unlock_regular_v4_frontier_repair_settlement_held;", heldTail, StringComparison.Ordinal);
            Assert.Contains("decision_reason=awaiting_receive_recovery_lifecycle_boundary", heldTail, StringComparison.Ordinal);
            Assert.DoesNotContain("event=runtime_unlock_regular_v4_frontier_repair_settlement_handoff_consumed;", heldTail, StringComparison.Ordinal);
            Assert.DoesNotContain("event=runtime_unlock_retry_dispatch_authority_rejected;", heldTail, StringComparison.Ordinal);
            Assert.DoesNotContain("event=regular_v4_receive_recovery_contract_closed_no_deferral;", heldTail, StringComparison.Ordinal);
            var recoveryState = Assert.IsAssignableFrom<IFileTransferRecoveryLivenessState>(host);
            Assert.True(recoveryState.TryGetActiveFileTransferRecoveryLivenessSnapshot(sessionId, out _));

            InvokePrivateMethod(
                host,
                "MarkFileTransferRegularV4RecoveryLivenessBridgeRecoveryLifecycle",
                "completed",
                "test_regular_v4_recovery_completed_without_receive_proof");
            await WaitUntilAsync(
                () => ReadOperationalLogTail(logStart).Contains(
                    "event=runtime_unlock_regular_v4_recovery_lease_closure_retained;",
                    StringComparison.Ordinal),
                TimeSpan.FromSeconds(3));

            var requestCountBeforeClosureRecheck = Volatile.Read(ref authorityRequestCount);
            InvokePrivateMethod(
                host,
                "ScheduleRuntimeUnlockRetryAfterRecoveryIfArmed",
                "bridge_lifecycle_completed");
            await WaitUntilAsync(
                () => ReadOperationalLogTail(logStart).Contains(
                    "event=runtime_unlock_retry_regular_v4_recovery_lease_closure_hold_preserved;",
                    StringComparison.Ordinal),
                TimeSpan.FromSeconds(3));

            var closureHeldTail = ReadOperationalLogTail(logStart);
            Assert.Equal(requestCountBeforeClosureRecheck, Volatile.Read(ref authorityRequestCount));
            Assert.Contains("decision_reason=awaiting_local_receive_proof", closureHeldTail, StringComparison.Ordinal);
            Assert.DoesNotContain("event=runtime_unlock_retry_dispatch_authority_rejected;", closureHeldTail, StringComparison.Ordinal);
            Assert.DoesNotContain("event=runtime_unlock_retry_rejected_after_regular_v4_receive_recovery;", closureHeldTail, StringComparison.Ordinal);
            Assert.DoesNotContain("event=runtime_unlock_regular_v4_frontier_repair_settlement_handoff_consumed;", closureHeldTail, StringComparison.Ordinal);
            Assert.DoesNotContain("event=session_recovery_contract_failed;", closureHeldTail, StringComparison.Ordinal);

            var blockedRetryState = Assert.IsAssignableFrom<object>(
                GetPrivateField(host, "runtimeUnlockRecoveryRetryState"));
            var blockedRetryStateType = blockedRetryState.GetType();
            Assert.Equal(
                0L,
                Assert.IsType<long>(blockedRetryStateType.GetProperty("RetryDeadlineUtcMs")!.GetValue(blockedRetryState)));
            Assert.Equal(
                0L,
                Assert.IsType<long>(blockedRetryStateType.GetProperty("DispatchDeadlineUtcMs")!.GetValue(blockedRetryState)));
            Assert.Equal(
                0L,
                Assert.IsType<long>(blockedRetryStateType.GetProperty("ObservedSendDeadlineUtcMs")!.GetValue(blockedRetryState)));

            coordinatorStatus = RuntimeUnlockRetryDispatchDecisionStatus.Granted;
            InvokePrivateMethod(
                host,
                "MarkFileTransferRegularV4RecoveryLivenessReceiveProofReceived",
                sessionId,
                transferId,
                "test_receive_proof",
                "control");
            await WaitUntilAsync(
                () => Volatile.Read(ref authorityRequestCount) == requestCountBeforeClosureRecheck + 1 &&
                      ReadOperationalLogTail(logStart).Contains(
                          "event=runtime_unlock_regular_v4_recovery_lease_closure_consumed;",
                          StringComparison.Ordinal),
                TimeSpan.FromSeconds(3));

            var releasedTail = ReadOperationalLogTail(logStart);
            Assert.Contains("event=runtime_unlock_regular_v4_recovery_lease_closure_adopted;", releasedTail, StringComparison.Ordinal);
            Assert.Contains("event=runtime_unlock_regular_v4_frontier_repair_settlement_handoff_discarded;", releasedTail, StringComparison.Ordinal);
            Assert.Contains("event=runtime_unlock_retry_dispatch_authority_granted;", releasedTail, StringComparison.Ordinal);
            Assert.Contains("dispatch_attempt_generation=1", releasedTail, StringComparison.Ordinal);
            Assert.Contains("missing_dispatch_successor_generation=0", releasedTail, StringComparison.Ordinal);
            Assert.Contains("predecessor_authority_id=(none)", releasedTail, StringComparison.Ordinal);
        }
        finally
        {
            NknSignalingTransport.HelperPaidOfferHelpeePriorityDelayOverrideForTests = previousHelpeePriorityDelay;
            NknSignalingTransport.RuntimeUnlockRecoverySoftSettleDelayOverrideForTests = previousSoftSettleDelay;
            NknSignalingTransport.RuntimeUnlockRegularV4ReceiveRecoveryBlockerOverrideForTests = previousReceiveRecoveryBlocker;
            NknSignalingTransport.RuntimeUnlockOfferObservedSendBlockerReasonOverrideForTests = previousObservedSendBlocker;
            NknSignalingTransport.RuntimeUnlockRetryAuthorityPeerProofFreshnessOverrideForTests = previousPeerProofFreshness;
            NknSignalingTransport.RuntimeUnlockBulkQueueObservedProofBlockerOverrideForTests = previousBulkProofBlocker;
            NknSignalingTransport.RuntimeUnlockOfferDirectObservedLaneBlockerOverrideForTests = previousDirectObservedLaneBlocker;
            NknSignalingTransport.RuntimeUnlockPeerVisibleLifecycleCopyTimeoutOverrideForTests = previousPeerVisibleCopyTimeout;
            FakeNknClient.ResetNetwork();
        }
    }

