            await WaitUntilAsync(
                () => host.IsAccelerationAvailableForTests && helper.IsAccelerationAvailableForTests,
                TimeSpan.FromSeconds(8));

            Assert.True(Volatile.Read(ref offerSendCount) >= 4);
