                new NknIdentity("host-tuna-probe-sidecar-close-rearm-id", hostClient.Address),
                NknTunaAccelerationOptions.Disabled,
                hostLane);
            using var helper = new NknSignalingTransport(
                helperClient,
                options,
                new NknIdentity("helper-tuna-probe-sidecar-close-rearm-id", helperClient.Address));

            var sessionId = await ApproveNknSessionAsync(
                host,
                helper,
                cts.Token,
                InviteCapabilities.Chat | InviteCapabilities.FileTransfer | InviteCapabilities.ScreenShare);
            const string transferId = "transfer_tuna_probe_sidecar_close_rearm";
            _ = await host.OpenFileTransferDataSessionAsync(sessionId, transferId, cts.Token);
            InvokePrivateMethod(
                host,
                "TrackAuthorizedFileTransferRouteHintForTests",
                transferId,
                FileTransferRouteResolver.RegularNknV4FastToken,
                FileTransferProtocol.ProtocolVersionV4,
                "test_regular_route");
            host.SetAccelerationAcceptedForTests(NknAccelerationLaneKind.File | NknAccelerationLaneKind.Screen, sessionId);
            hostLane.MarkListenerAvailableForTests();
            InvokePrivateMethod(
                host,
                "ApplyRuntimeUnlockTransaction",
                RuntimeUnlockTransactionEventKind.OfferGenerationCreated,
                sessionId,
                7L,
                "runtime_unlock",
                null);
            InvokePrivateMethod(
                host,
                "ApplyRuntimeUnlockTransaction",
                RuntimeUnlockTransactionEventKind.PeerReceived,
                sessionId,
                7L,
                "transport_acceleration_offer_received",
                null);
            InvokePrivateMethod(
                host,
                "ApplyRuntimeUnlockTransaction",
                RuntimeUnlockTransactionEventKind.AnswerReceived,
                sessionId,
                7L,
                "transport_acceleration_answer_received",
                null);
            var proofProvider = Assert.IsAssignableFrom<IRuntimeUnlockRouteCommitProofProvider>(host);
            proofProvider.NotifyRuntimeUnlockPathProbeStarted(
                sessionId,
                transferId,
                transportEpoch: 1,
                probeId: "runtime-unlock-precommit:1:7:sidecar-close",
                FileTransferTransportKind.Tuna,
                reason: "precommit_probe_sent");

            var logStart = GetOperationalLogLength();
            await hostLane.StopAsync("sidecar_tuna_stream_eof", cts.Token);

            await WaitUntilAsync(
                () => ReadOperationalLogTail(logStart).Contains(
                    "event=runtime_unlock_precommit_probe_sidecar_rearm_scheduled;",
                    StringComparison.Ordinal),
                TimeSpan.FromSeconds(5));

            var tail = ReadOperationalLogTail(logStart);
            Assert.Contains("event=runtime_unlock_tuna_probe_sidecar_failure;", tail, StringComparison.Ordinal);
            Assert.Contains("retry_reason=runtime_unlock_tuna_probe_sidecar_closed", tail, StringComparison.Ordinal);
            Assert.Contains("event=runtime_unlock_precommit_probe_sidecar_rearm_scheduled;", tail, StringComparison.Ordinal);
            Assert.DoesNotContain("event=runtime_unlock_tuna_probe_sidecar_closed_fresh_transaction_scheduled;", tail, StringComparison.Ordinal);
            Assert.Contains("event=tuna_acceleration_runtime_unlock_listener_rearm_after_sidecar_drop;", tail, StringComparison.Ordinal);
            Assert.DoesNotContain("listener_ready_reuse=1", tail, StringComparison.Ordinal);
            var dispatchGrantIndex = tail.IndexOf(
                "event=runtime_unlock_retry_dispatch_authority_granted;",
                StringComparison.Ordinal);
            var retryScheduleIndex = tail.IndexOf(
                "event=tuna_acceleration_retry_scheduled; reason=runtime_unlock_tuna_probe_sidecar_closed",
                StringComparison.Ordinal);
            var offerGenerationIndex = tail.IndexOf(
                "event=runtime_unlock_transaction_offer_generation_created;",
                StringComparison.Ordinal);
            if (retryScheduleIndex >= 0)
            {
                Assert.True(
                    dispatchGrantIndex >= 0 && dispatchGrantIndex < retryScheduleIndex,
                    "Runtime-unlock retry scheduling must be preceded by dispatch authority after listener rearm.");
            }

            if (offerGenerationIndex >= 0)
            {
                Assert.True(
                    dispatchGrantIndex >= 0 && dispatchGrantIndex < offerGenerationIndex,
                    "Runtime-unlock offer generation must be preceded by dispatch authority after listener rearm.");
            }
        }
        finally
        {
            NknSignalingTransport.HelperPaidOfferHelpeePriorityDelayOverrideForTests = previousHelpeePriorityDelay;
            NknSignalingTransport.RuntimeUnlockRecoverySoftSettleDelayOverrideForTests = previousSoftSettleDelay;
            FakeNknClient.ResetNetwork();
        }
    }

    [Fact]
    [Trait("Category", "Smoke")]
    public async Task TransportAccelerationStop_ResumesRegularNknBeforeBlockedDownNotificationCompletes()
    {
        FakeNknClient.ResetNetwork();
        var blockedDownNotification = new TaskCompletionSource<object?>(TaskCreationOptions.RunContinuationsAsynchronously);
        try
        {
            using var cts = new CancellationTokenSource(TimeSpan.FromSeconds(25));
            var options = NknTransportOptions.Load();
            var hostClient = new FakeNknClient("host.tuna.stop-blocked-down.address");
            var helperClient = new FakeNknClient("helper.tuna.stop-blocked-down.address");
            var hostLane = new FakeNknAccelerationLane();
            var helperLane = new FakeNknAccelerationLane();
            var blockedDownCount = 0;
            hostClient.BeforeSendAsync = async (destination, payload, ct) =>
            {
                if (string.Equals(destination, helperClient.ConnectedAddress, StringComparison.Ordinal) &&
                    EnvelopeCodec.TryDeserialize(payload, out var envelope) &&
                    envelope.Type == MsgType.TransportAccelerationDown)
                {
                    Interlocked.Increment(ref blockedDownCount);
                    await blockedDownNotification.Task.WaitAsync(ct).ConfigureAwait(false);
                }
            };
            using var host = new NknSignalingTransport(
                hostClient,
                options,
                new NknIdentity("host-tuna-stop-blocked-down-id", hostClient.Address),
                NknTunaAccelerationOptions.Disabled,
                hostLane);
            using var helper = new NknSignalingTransport(
                helperClient,
                options,
                new NknIdentity("helper-tuna-stop-blocked-down-id", helperClient.Address),
                NknTunaAccelerationOptions.Disabled,
                helperLane);

            var sessionId = await ApproveNknSessionAsync(
                host,
                helper,
                cts.Token,
                InviteCapabilities.Chat | InviteCapabilities.FileTransfer | InviteCapabilities.ScreenShare);
            _ = await host.OpenFileTransferDataSessionAsync(
                sessionId,
                "transfer_tuna_stop_blocked_down",
                cts.Token);
            host.SetAccelerationAcceptedForTests(NknAccelerationLaneKind.File | NknAccelerationLaneKind.Screen, sessionId);
            helper.SetAccelerationAcceptedForTests(NknAccelerationLaneKind.File | NknAccelerationLaneKind.Screen, sessionId);
            var logStart = GetOperationalLogLength();

            var stopTask = ((ITransportAccelerationControl)host).StopAccelerationAsync("header_switch_off", cts.Token);

            await WaitUntilAsync(() => Volatile.Read(ref blockedDownCount) > 0, TimeSpan.FromSeconds(2));
            Assert.True(stopTask.IsCompletedSuccessfully);
            Assert.False(host.IsAccelerationAvailableForTests);
            Assert.True(host.IsAccelerationUserStoppedForCurrentSessionForTests);
            Assert.True(host.AccelerationDiagnosticsForTests.FallbackEpoch > 0);

            var logTail = ReadOperationalLogTail(logStart);
            Assert.Contains("event=tuna_acceleration_user_stop_filetransfer_fallback_forced;", logTail, StringComparison.Ordinal);
            Assert.Contains("event=tuna_acceleration_reset; reason=header_switch_off; fallback_proof_suppressed=0", logTail, StringComparison.Ordinal);
            Assert.Contains("event=tuna_fallback_started;", logTail, StringComparison.Ordinal);
            Assert.Contains("lanes=file", logTail, StringComparison.Ordinal);
            Assert.Contains("event=tuna_fallback_filetransfer_rebind_requested;", logTail, StringComparison.Ordinal);
        }
        finally
        {
            blockedDownNotification.TrySetResult(null);
            FakeNknClient.ResetNetwork();
        }
    }

