    [Theory]
    [Trait("Category", "Smoke")]
    [InlineData("nonce_mismatch", "reason=nonce_mismatch")]
    [InlineData("session_id_mismatch", "reason=session_id_mismatch")]
    [InlineData("source_identity_mismatch", "reason=source_identity_mismatch")]
