    private new static object? InvokePrivateMethod(
        object target,
        string methodName,
        params object?[] args)
    {
        if (string.Equals(
                methodName,
                "MarkFileTransferRegularV4RecoveryLivenessStarted",
                StringComparison.Ordinal) &&
            args.Length > 0 &&
            args[0] is FileTransferReceiveRecoveryRequest request &&
            request.RegularV4RecoveryAuthority is null)
        {
            args[0] = AttachRegularV4RecoveryAuthorityForTests(request);
        }

        return CoreSmokeTestsBase.InvokePrivateMethod(target, methodName, args);
    }

    private static FileTransferReceiveRecoveryRequest AttachRegularV4RecoveryAuthorityForTests(
        FileTransferReceiveRecoveryRequest request,
        int leaseGeneration = 1)
    {
        var routeToken = request.RouteToken ?? FileTransferRouteResolver.RegularNknV4FastToken;
        Assert.True(FileTransferRouteResolver.TryParseTelemetryToken(routeToken, out var route));
        var reason = string.IsNullOrWhiteSpace(request.Reason)
            ? "test_regular_v4_recovery"
            : request.Reason.Trim();
        var bridge = request.BridgeRecoveryAuthority is { } suppliedBridge
            ? suppliedBridge with
            {
                TransferLegGeneration = Math.Max(1, suppliedBridge.TransferLegGeneration),
                RecoveryKind = nameof(BridgeRecoveryKind.BridgeReceiveStallRecovery),
            }
            : new FileTransferBridgeRecoveryAuthority(
                request.SessionId,
                request.TransferId,
                request.Direction,
                routeToken,
                request.ProtocolVersion,
                request.LiveRouteEpoch,
                RuntimeGeneration: 1,
                TerminalGeneration: 0,
                Math.Max(1, request.TransferLegGeneration),
                request.TransportEpoch,
                request.BridgeRecoveryGeneration,
                BridgeDecisionGeneration: 1,
                RecoveryKind: nameof(BridgeRecoveryKind.BridgeReceiveStallRecovery),
                Reason: reason);
        var owner = new RuntimeOwnerToken(
            bridge.SessionId,
            bridge.TransferId,
            bridge.Direction,
            route,
            bridge.RouteToken,
            bridge.ProtocolVersion,
            bridge.LiveRouteEpoch,
            bridge.RuntimeGeneration,
            bridge.TerminalGeneration,
            "test_runtime",
            "test_coordinator_fixture");
        var lease = new RecoveryLivenessLease(
            bridge.SessionId,
            bridge.TransferId,
            bridge.Direction,
            owner,
            route,
            bridge.RouteToken,
            bridge.ProtocolVersion,
            bridge.LiveRouteEpoch,
            bridge.RuntimeGeneration,
            bridge.TerminalGeneration,
            bridge.TransferLegGeneration,
            bridge.TransportEpoch,
            bridge.BridgeRecoveryGeneration,
            Math.Max(1, leaseGeneration),
            new FileTransferAuthorityId(
                $"fta{FileTransferAuthoritySchema.Current}-test_regular_v4_recovery-{Math.Max(1, leaseGeneration):D8}"),
            RecoveryLivenessLeaseState.Active,
            bridge.Reason);
        return request with
        {
            RouteToken = bridge.RouteToken,
            ProtocolVersion = bridge.ProtocolVersion,
            LiveRouteEpoch = bridge.LiveRouteEpoch,
            TransferLegGeneration = bridge.TransferLegGeneration,
            TransportEpoch = bridge.TransportEpoch,
            BridgeRecoveryGeneration = bridge.BridgeRecoveryGeneration,
            BridgeRecoveryAuthority = bridge,
            RegularV4RecoveryAuthority = new RuntimeUnlockRegularV4RecoveryAuthority(bridge, lease),
        };
    }

    private static async Task<long> EstablishDispatchObservedRuntimeUnlockRetryForClosureJoinAsync(
        NknSignalingTransport transport,
        ConcurrentQueue<RuntimeUnlockRetryDispatchAuthorityRequest> authorityRequests,
        string sessionId,
        long retiredOfferGeneration,
        long observedOfferGeneration,
        string offerNonce)
    {
        var logStart = GetOperationalLogLength();
        InvokePrivateMethod(
            transport,
            "ArmRuntimeUnlockRetryAfterRecovery",
            retiredOfferGeneration,
            sessionId,
            "runtime_unlock_offer_send_not_observed",
            "regular_v4_repair_settled",
            false);
        Assert.Single(authorityRequests);
        InvokePrivateMethod(transport, "MarkRuntimeUnlockRecoveryContractRetryDispatched", "runtime_unlock");
        Assert.True(transport.BindRuntimeUnlockRetryDispatchOfferAliasForTests(
            observedOfferGeneration,
            offerNonce));
        Assert.True(transport.BeginRuntimeUnlockRetryDispatchSendForTests());
        Assert.True(Assert.IsType<bool>(InvokePrivateMethod(
            transport,
            "MarkRuntimeUnlockRecoveryContractRetryObserved",
            sessionId,
            observedOfferGeneration,
            "control_to_bulk_endpoint")));
        await WaitUntilAsync(
            () => ReadOperationalLogTail(logStart).Contains(
                "event=runtime_unlock_retry_dispatch_observed;",
                StringComparison.Ordinal),
            TimeSpan.FromSeconds(3));

        var state = GetPrivateField(transport, "runtimeUnlockRecoveryRetryState");
        Assert.NotNull(state);
        var contract = Assert.IsType<RuntimeUnlockRetryDispatchContract>(
            state!.GetType().GetProperty("DispatchContract")!.GetValue(state));
        Assert.True(contract.Lifecycle.IsSettled);
        Assert.Equal(
            RuntimeUnlockRetryDispatchSettlementOutcome.DispatchObserved,
            contract.Lifecycle.SettlementOutcome);
        Assert.NotNull(state.GetType().GetProperty("LastAppliedDispatchSettlementReport")!.GetValue(state));
        return Assert.IsType<long>(
            state.GetType().GetProperty("ContractGeneration")!.GetValue(state));
    }

    private static async Task<FileTransferReceiveRecoveryRequest>
        RetainRuntimeUnlockRegularV4RecoveryClosureForJoinAsync(
            NknSignalingTransport transport,
            string sessionId,
            string transferId,
            int liveRouteEpoch)
    {
        var request = AttachRegularV4RecoveryAuthorityForTests(
            new FileTransferReceiveRecoveryRequest(
                sessionId,
                transferId,
                FileTransferDirection.Outbound,
                "session_liveness_timeout_pending")
            {
                RouteToken = FileTransferRouteResolver.RegularNknV4FastToken,
                ProtocolVersion = FileTransferProtocol.ProtocolVersionV4,
                LiveRouteEpoch = liveRouteEpoch,
                TransferLegGeneration = 1,
                AuthorityReason = "regular_v4_receive_recovery_pending",
            });
        InvokePrivateMethod(
            transport,
            "MarkFileTransferRegularV4RecoveryLivenessStarted",
            request,
            sessionId,
            transferId,
            "session_liveness_timeout_pending");
        var logStart = GetOperationalLogLength();
        InvokePrivateMethod(
            transport,
            "MarkFileTransferRegularV4RecoveryLivenessBridgeRecoveryLifecycle",
            "completed",
            "test_regular_v4_recovery_completed");
        await WaitUntilAsync(
            () => ReadOperationalLogTail(logStart).Contains(
                "event=runtime_unlock_regular_v4_recovery_lease_closure_retained;",
                StringComparison.Ordinal),
            TimeSpan.FromSeconds(3));
        return request;
    }

    private static (object Intent, bool Duplicate)
        CaptureRuntimeUnlockRegularV4RecoveryRetryJoinIntentForTests(
            NknSignalingTransport transport,
            string sessionId,
            string offerNonce,
            long offerPayerDecisionId,
            long offerGeneration,
            string purpose = "offer_answer",
            string trigger = "answer_timeout_without_peer_response",
            string retryReason = "runtime_unlock_offer_peer_response_timeout",
            string recoveryReason = "tuna_activation_offer_peer_response_timeout")
    {
        var method = Assert.Single(
            typeof(NknSignalingTransport)
                .GetMethods(BindingFlags.Instance | BindingFlags.NonPublic)
                .Where(candidate =>
                    string.Equals(
                        candidate.Name,
                        "TryCaptureRuntimeUnlockRegularV4RecoveryRetryJoinIntent",
                        StringComparison.Ordinal) &&
                    candidate.GetParameters().Length == 10));
        object?[] arguments =
        [
            purpose,
            sessionId,
            trigger,
            offerNonce,
            offerPayerDecisionId,
            offerGeneration,
            retryReason,
            recoveryReason,
            null,
            false,
        ];
        var captured = Assert.IsType<bool>(method.Invoke(transport, arguments));
        Assert.True(captured);
        Assert.NotNull(arguments[8]);
        return (arguments[8]!, Assert.IsType<bool>(arguments[9]));
    }

    private static (object State, RuntimeUnlockRetryDispatchAuthorityRequest Request)
        SeedHeldFallbackTailRuntimeUnlockRetryForTests(
            NknSignalingTransport transport,
            string sessionId,
            string transferId,
            FileTransferDirection direction = FileTransferDirection.Outbound,
            long contractGeneration = 1,
            long retiredOfferGeneration = 2,
            int dispatchAttemptGeneration = 1,
            int missingDispatchSuccessorGeneration = 0,
            FileTransferAuthorityId? predecessorAuthorityId = null,
            bool requestActivePredecessorSupersession = false)
    {
        SetPrivateField(
            transport,
            "currentSessionSecurityState",
            SessionSecurityState.Empty with { SessionId = new SessionId(sessionId) });
        var publication = new FileTransferRoutePublicationAuthority(
            sessionId,
            transferId,
            direction,
            FileTransferRouteResolver.PostTunaFallbackV6Token,
            FileTransferProtocol.ProtocolVersionV6,
            LiveRouteEpoch: 4,
            RuntimeGeneration: 3,
            TerminalGeneration: 1,
            LegGeneration: 3,
            RoutePublicationGeneration: 5,
            RouteCommitGeneration: 4,
            FileTransferRouteResolver.FileTunaV4Token,
            FileTransferProtocol.ProtocolVersionV4,
            FileTransferTransportKind.Tuna,
            FileTransferCoordinatorActionKind.RoutePublication.ToString(),
            "test_post_tuna_fallback_publication");
        var request = new RuntimeUnlockRetryDispatchAuthorityRequest(
            sessionId,
            transferId,
            direction,
            publication,
            contractGeneration,
            retiredOfferGeneration,
            dispatchAttemptGeneration,
            "runtime_unlock_offer_send_not_observed",
            "post_tuna_fallback_repair_recovered",
            RegularV4LivenessGeneration: 0,
            BridgeDecisionGeneration: 0,
            predecessorAuthorityId,
            requestActivePredecessorSupersession,
            missingDispatchSuccessorGeneration);

        var stateType = typeof(NknSignalingTransport).GetNestedType(
            "RuntimeUnlockRecoveryRetryState",
            BindingFlags.NonPublic);
        Assert.NotNull(stateType);
        var state = Activator.CreateInstance(stateType!, nonPublic: true);
        Assert.NotNull(state);
        void Set(string propertyName, object? value)
        {
            var property = stateType!.GetProperty(
                propertyName,
                BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
            Assert.NotNull(property);
            property!.SetValue(state, value);
        }

        Set("ContractGeneration", contractGeneration);
        Set("RetiredOfferGeneration", retiredOfferGeneration);
        Set("SessionId", sessionId);
        Set("TransferId", transferId);
        Set("RetryReason", request.RetryReason);
        Set("RecoveryReason", request.RecoveryReason);
        Set("CreatedUtcMs", DateTimeOffset.UtcNow.ToUnixTimeMilliseconds());
        Set("ContractState", SessionRecoveryContractState.RecoverySettled);
        Set("RetryAuthorityPending", true);
        Set("DispatchAttemptGeneration", dispatchAttemptGeneration);
        Set("MissingDispatchSuccessorGeneration", missingDispatchSuccessorGeneration);
        Set("SourcePublicationAuthority", publication);
        Set("PendingDispatchAuthorityRequest", request);
        Set("DispatchDecisionStatus", RuntimeUnlockRetryDispatchDecisionStatus.Held);
        Set("DispatchDecisionReason", "fallback_paired_tail_yield_pending");
        Set("AuthorityFailureReason", "fallback_paired_tail_yield_pending");
        if (predecessorAuthorityId is { } predecessor)
        {
            var successorType = typeof(NknSignalingTransport).GetNestedType(
                "RuntimeUnlockRetrySuccessorIntent",
                BindingFlags.NonPublic);
            Assert.NotNull(successorType);
            var successor = Activator.CreateInstance(
                successorType!,
                BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic,
                binder: null,
                args:
                [
                    retiredOfferGeneration,
                    dispatchAttemptGeneration,
                    missingDispatchSuccessorGeneration,
                    sessionId,
                    request.RetryReason,
                    request.RecoveryReason,
                    false,
                    predecessor,
                    requestActivePredecessorSupersession,
                ],
                culture: null);
            Assert.NotNull(successor);
            Set("PendingDispatchSuccessorIntent", successor);
            Set("PendingDispatchSuccessorRequestIssued", true);
            Set("PendingDispatchSuccessorRequestHeld", true);
        }

        SetPrivateField(transport, "runtimeUnlockRecoveryRetryState", state);
        return (state!, request);
    }

