    private static void InstallRuntimeUnlockRetryDispatchCoordinatorForTests(
        NknSignalingTransport transport,
        Func<RuntimeUnlockRetryDispatchAuthorityRequest, RuntimeUnlockRetryDispatchDecisionStatus>? statusSelector = null,
        Func<RuntimeUnlockRetryDispatchAuthorityRequest, int>? bridgeDecisionGenerationSelector = null,
        Func<RuntimeUnlockRetryDispatchDecision, RuntimeUnlockRetryDispatchDecision>? decisionTransform = null,
        bool installSettlementObserver = true,
        Func<RuntimeUnlockRetryDispatchSettlementDecision, RuntimeUnlockRetryDispatchSettlementDecision>?
            settlementDecisionTransform = null,
        Func<RuntimeUnlockRetryDispatchSettlementReport, bool>? terminalStateSelector = null,
        Action<RuntimeUnlockRegularV4RecoverySettlementDecision, bool>? regularV4DecisionObserved = null,
        FileTransferRegularV4FrontierRepairSettlement? regularV4CoordinatorIssuedSettlement = null)
    {
        FileTransferCoordinatorState? coordinatorState = null;
        RuntimeUnlockRetryDispatchContract? coordinatorContract = null;
        RuntimeUnlockRetryDispatchSettlementReport? lastSettlement = null;
        RuntimeUnlockRegularV4RecoverySettlementReport? lastRegularV4Handoff = null;
        RuntimeUnlockRegularV4RecoveryLifecycleReport? lastRegularV4Lifecycle = null;
        var bridge = Assert.IsAssignableFrom<IRuntimeUnlockRetryDispatchAuthorityBridge>(transport);

        FileTransferCoordinatorState CreateCoordinatorState(
            RuntimeUnlockRetryDispatchAuthorityRequest request,
            bool prepareRetryRelease = true)
        {
            var publication = request.SourcePublicationAuthority;
            Assert.True(FileTransferRouteResolver.TryParseTelemetryToken(publication.RouteToken, out var route));
            Assert.True(FileTransferRouteResolver.TryParseTelemetryToken(publication.TargetRouteToken, out var targetRoute));
            var routeSelection = FileTransferRouteResolver.Resolve(route);
            var runtimeOwner = new RuntimeOwnerToken(
                request.SessionId,
                request.TransferId,
                request.Direction,
                route,
                publication.RouteToken,
                publication.ProtocolVersion,
                publication.LiveRouteEpoch,
                publication.RuntimeGeneration,
                publication.TerminalGeneration,
                "test_runtime",
                "test_coordinator_fixture");
            var sourcePublication = new RoutePublicationToken(
                request.SessionId,
                request.TransferId,
                request.Direction,
                runtimeOwner,
                route,
                publication.RouteToken,
                publication.ProtocolVersion,
                publication.LiveRouteEpoch,
                publication.RuntimeGeneration,
                publication.TerminalGeneration,
                checked((int)publication.LegGeneration),
                publication.RouteCommitGeneration,
                targetRoute,
                publication.TargetProtocolVersion,
                publication.TargetTransport,
                publication.RoutePublicationGeneration,
                FileTransferCoordinatorActionKind.RoutePublication,
                publication.CoordinatorDecisionReason);
            var leg = new FileTransferLeg
            {
                LegId = $"test-runtime-unlock-leg-{request.Direction.ToString().ToLowerInvariant()}",
                Generation = checked((int)publication.LegGeneration),
                RouteSelection = routeSelection,
                ProtocolVersion = publication.ProtocolVersion,
                LiveRouteEpochId = publication.LiveRouteEpoch,
                TransportEpochId = 0,
                BridgeRecoveryGeneration = 0,
                StartedUtc = DateTimeOffset.UtcNow,
                State = FileTransferLegState.Active,
                CanSendData = true,
            };
            var liveRouteEpoch = publication.LiveRouteEpoch > 0
                ? new LiveRouteEpoch
                {
                    EpochId = publication.LiveRouteEpoch,
                    RouteSelection = routeSelection,
                    HandoffKind = FileTransferTransportHandoffKind.None,
                    TargetTransport = publication.TargetTransport,
                    Reason = "test_coordinator_fixture",
                    State = "started",
                    RoutePublicationToken = sourcePublication,
                }
                : null;
            var bridgeDecisionGeneration =
                bridgeDecisionGenerationSelector?.Invoke(request) ?? request.BridgeDecisionGeneration;
            var preparesRecoveryLeaseClosure =
                route == FileTransferRoute.RegularNknV4Fast &&
                prepareRetryRelease &&
                (request.RegularV4LivenessGeneration > 0 || request.BridgeDecisionGeneration > 0);
            BridgeRecoveryDecision? currentBridgeDecision = bridgeDecisionGeneration > 0
                ? new BridgeRecoveryDecision(
                    true,
                    preparesRecoveryLeaseClosure
                        ? BridgeRecoveryKind.BridgeReceiveStallRecovery
                        : BridgeRecoveryKind.ReceiveRecoveryRequest,
                    preparesRecoveryLeaseClosure
                        ? "test_receive_recovery_started"
                        : "test_coordinator_fixture",
                    bridgeDecisionGeneration,
                    route,
                    publication.ProtocolVersion,
                    publication.LiveRouteEpoch,
                    publication.RuntimeGeneration,
                    publication.TerminalGeneration,
                    checked((int)publication.LegGeneration),
                    leg.TransportEpochId,
                    leg.BridgeRecoveryGeneration,
                    runtimeOwner)
                : null;

            var releaseAuthorityId = new FileTransferAuthorityId(
                $"test-runtime-unlock-release-{request.RecoveryContractGeneration}");
            const int releaseGeneration = 1;
            RecoveryLivenessLease? retiredLease = null;
            RuntimeUnlockRegularV4RecoveryLifecycleReport? acceptedRecoveryLifecycle = null;
            RepairReplayDecision? repairDecision = null;
            FileTransferRegularV4FrontierRepairSettlement? issuedRepairSettlement = null;
            RuntimeUnlockRegularV4RecoverySettlementReport? consumedRepairSettlement = null;
            FallbackTailYieldDecision? fallbackTailYield = null;
            var fallbackSurvival = RuntimeUnlockFallbackSurvivalState.Empty;
            if (preparesRecoveryLeaseClosure)
            {
                var lifecycleBridgeGeneration = Math.Max(1, request.BridgeDecisionGeneration);
                var lifecycleLeaseGeneration = Math.Max(1, request.RegularV4LivenessGeneration);
                var bridgeAuthority = new FileTransferBridgeRecoveryAuthority(
                    request.SessionId,
                    request.TransferId,
                    request.Direction,
                    publication.RouteToken,
                    publication.ProtocolVersion,
                    publication.LiveRouteEpoch,
                    publication.RuntimeGeneration,
                    publication.TerminalGeneration,
                    checked((int)publication.LegGeneration),
                    leg.TransportEpochId,
                    leg.BridgeRecoveryGeneration,
                    lifecycleBridgeGeneration,
                    nameof(BridgeRecoveryKind.BridgeReceiveStallRecovery),
                    "test_receive_recovery_started");
                var activeLease = new RecoveryLivenessLease(
                    request.SessionId,
                    request.TransferId,
                    request.Direction,
                    runtimeOwner,
                    route,
                    publication.RouteToken,
                    publication.ProtocolVersion,
                    publication.LiveRouteEpoch,
                    publication.RuntimeGeneration,
                    publication.TerminalGeneration,
                    checked((int)publication.LegGeneration),
                    leg.TransportEpochId,
                    leg.BridgeRecoveryGeneration,
                    lifecycleLeaseGeneration,
                    new FileTransferAuthorityId(
                        $"test-runtime-unlock-release-{request.RecoveryContractGeneration}-{lifecycleLeaseGeneration}"),
                    RecoveryLivenessLeaseState.Active,
                    bridgeAuthority.Reason);
                const string lifecycleReason = "test_receive_recovery_completed";
                acceptedRecoveryLifecycle = new RuntimeUnlockRegularV4RecoveryLifecycleReport(
                    new RuntimeUnlockRegularV4RecoveryAuthority(bridgeAuthority, activeLease),
                    RuntimeUnlockRegularV4RecoveryLifecycleOutcome.Completed,
                    lifecycleReason);
                retiredLease = activeLease with
                {
                    State = RecoveryLivenessLeaseState.Retired,
                    Reason = lifecycleReason,
                };
            }
            else if (route == FileTransferRoute.RegularNknV4Fast && prepareRetryRelease)
            {
                var repairAuthorityId = regularV4CoordinatorIssuedSettlement?.AuthorityId ??
                    new FileTransferAuthorityId(
                        $"test-runtime-unlock-repair-{request.RecoveryContractGeneration}");
                repairDecision = new RepairReplayDecision(
                    Accepted: true,
                    RepairReplayKind.V4Repair,
                    regularV4CoordinatorIssuedSettlement?.DecisionReason ??
                        "test_regular_v4_repair_settled",
                    regularV4CoordinatorIssuedSettlement?.DecisionGeneration ?? releaseGeneration,
                    route,
                    publication.ProtocolVersion,
                    regularV4CoordinatorIssuedSettlement?.LiveRouteEpoch ?? publication.LiveRouteEpoch,
                    regularV4CoordinatorIssuedSettlement?.RuntimeGeneration ?? publication.RuntimeGeneration,
                    regularV4CoordinatorIssuedSettlement?.TerminalGeneration ?? publication.TerminalGeneration,
                    checked((int)(regularV4CoordinatorIssuedSettlement?.LegGeneration ?? publication.LegGeneration)),
                    regularV4CoordinatorIssuedSettlement?.TransportEpoch ?? leg.TransportEpochId,
                    regularV4CoordinatorIssuedSettlement?.BridgeRecoveryGeneration ?? leg.BridgeRecoveryGeneration,
                    runtimeOwner,
                    repairAuthorityId,
                    PredecessorAuthorityId: null,
                    regularV4CoordinatorIssuedSettlement?.BridgeDecisionGeneration ?? 0,
                    sourcePublication);
                issuedRepairSettlement = regularV4CoordinatorIssuedSettlement ??
                    new FileTransferRegularV4FrontierRepairSettlement(
                        request.SessionId,
                        request.TransferId,
                        request.Direction,
                        publication.RouteToken,
                        publication.ProtocolVersion,
                        publication.LiveRouteEpoch,
                        publication.RuntimeGeneration,
                        publication.TerminalGeneration,
                        publication.LegGeneration,
                        leg.TransportEpochId,
                        leg.BridgeRecoveryGeneration,
                        BridgeDecisionGeneration: 0,
                        sourcePublication.PublicationGeneration,
                        sourcePublication.RouteCommitGeneration,
                        RepairKey: "test_regular_v4_repair",
                        FrontierChunkIndex: 0,
                        DurableReceivedHighestChunkIndex: 0,
                        RequestedChunkCount: 1,
                        DecisionGeneration: releaseGeneration,
                        DecisionReason: "test_regular_v4_repair_settled",
                        FileTransferRegularV4FrontierRepairSettlementOutcome.MissingDispatch,
                        FileTransferTransportKind.RegularNkn)
                    {
                        AuthorityId = repairAuthorityId,
                    };
                if (regularV4CoordinatorIssuedSettlement is null)
                {
                    consumedRepairSettlement = new RuntimeUnlockRegularV4RecoverySettlementReport(
                        issuedRepairSettlement,
                        RegularV4LivenessGeneration: 0,
                        BridgeDecisionGeneration: 0,
                        RuntimeUnlockRegularV4RecoverySettlementDisposition.Consumed,
                        "test_regular_v4_repair_consumed");
                }
            }
            else if (route != FileTransferRoute.RegularNknV4Fast)
            {
                Assert.Equal(FileTransferRoute.PostTunaFallbackV6, route);
                fallbackSurvival = new RuntimeUnlockFallbackSurvivalState(
                    FallbackActive: true,
                    FallbackCurrent: true,
                    FallbackTerminalized: false,
                    CheckpointDeliveryRecoveryPending: false,
                    StateRefreshSendInFlight: false,
                    DeferredStateRefreshPending: false,
                    ProofReplayPending: false,
                    ControlPlanePressurePending: false,
                    BridgeRecoveryPending: false,
                    FallbackTailRepairPending: false,
                    PairedFallbackYieldGranted: true);
                fallbackTailYield = new FallbackTailYieldDecision(
                    true,
                    FallbackTailYieldKind.Quiescent,
                    "test_paired_fallback_yield",
                    releaseGeneration,
                    "test_fallback_owner",
                    "test_fallback_pair",
                    string.Empty,
                    route,
                    publication.ProtocolVersion,
                    publication.LiveRouteEpoch,
                    publication.RuntimeGeneration,
                    publication.TerminalGeneration,
                    checked((int)publication.LegGeneration),
                    0,
                    null,
                    fallbackSurvival)
                {
                    AuthorityId = releaseAuthorityId,
                };
            }

            return new FileTransferCoordinatorState(
                request.SessionId,
                request.TransferId,
                request.Direction,
                false,
                routeSelection,
                liveRouteEpoch,
                leg,
                publication.LiveRouteEpoch,
                leg.Generation,
                publication.RuntimeGeneration,
                publication.TerminalGeneration,
                runtimeOwner,
                [leg],
                RuntimeUnlockFallbackSurvivalState: fallbackSurvival,
                LastFallbackTailYieldDecision: fallbackTailYield,
                LastFallbackTailYieldGeneration: fallbackTailYield?.YieldGeneration ?? 0,
                CurrentBridgeRecoveryDecision: currentBridgeDecision,
                LastBridgeRecoveryDecisionGeneration: bridgeDecisionGeneration,
                LastRecoveryLivenessLeaseGeneration: retiredLease?.LeaseGeneration ?? 0,
                CurrentRoutePublicationToken: sourcePublication,
                LastRoutePublicationGeneration: sourcePublication.PublicationGeneration,
                CurrentRepairReplayDecision: repairDecision,
                LastRepairReplayGeneration: repairDecision?.RepairGeneration ?? 0,
                LastRetiredRecoveryLivenessLease: retiredLease,
                LastRuntimeUnlockRegularV4RecoverySettlement: consumedRepairSettlement,
                LastCoordinatorIssuedRegularV4RecoverySettlement: issuedRepairSettlement,
                RuntimeUnlockRegularV4RecoverySettlementAvailable: consumedRepairSettlement.HasValue,
                LastRuntimeUnlockRegularV4RecoveryLifecycle: acceptedRecoveryLifecycle,
                RuntimeUnlockRecoveryLeaseClosureAvailable: acceptedRecoveryLifecycle.HasValue);
        }

        if (installSettlementObserver)
        {
            bridge.RuntimeUnlockRegularV4RecoveryLifecycleReported += (_, args) =>
            {
                var authority = args.Report.Authority;
                if (coordinatorState is null)
                {
                    var retryState = typeof(NknSignalingTransport).GetField(
                        "runtimeUnlockRecoveryRetryState",
                        BindingFlags.Instance | BindingFlags.NonPublic)?.GetValue(transport);
                    var publication = retryState?.GetType()
                        .GetProperty("SourcePublicationAuthority")?
                        .GetValue(retryState) as FileTransferRoutePublicationAuthority ??
                        new FileTransferRoutePublicationAuthority(
                        authority.SessionId,
                        authority.TransferId,
                        authority.Direction,
                        authority.RouteToken,
                        authority.ProtocolVersion,
                        authority.LiveRouteEpoch,
                        authority.RuntimeGeneration,
                        authority.TerminalGeneration,
                        authority.TransferLegGeneration,
                        RoutePublicationGeneration: 1,
                        RouteCommitGeneration: null,
                        FileTransferRouteResolver.RegularNknV4FastToken,
                        FileTransferProtocol.ProtocolVersionV4,
                        FileTransferTransportKind.RegularNkn,
                        FileTransferCoordinatorActionKind.RoutePublication.ToString(),
                        "test_lifecycle_bootstrap");
                    coordinatorState = CreateCoordinatorState(
                        new RuntimeUnlockRetryDispatchAuthorityRequest(
                            authority.SessionId,
                            authority.TransferId,
                            authority.Direction,
                            publication,
                            RecoveryContractGeneration: 1,
                            RetiredOfferGeneration: 0,
                            DispatchAttemptGeneration: 1,
                            RetryReason: "runtime_unlock_offer_send_not_observed",
                            RecoveryReason: "regular_v4_recovery_lifecycle",
                            args.Report.RegularV4LivenessGeneration,
                            authority.BridgeDecisionGeneration),
                        prepareRetryRelease: false);
                }

                if (lastRegularV4Lifecycle is null)
                {
                    var recoveryAuthority = args.Report.RecoveryAuthority;
                    var reportBridge = recoveryAuthority.BridgeRecoveryAuthority;
                    Assert.True(Enum.TryParse<BridgeRecoveryKind>(
                        reportBridge.RecoveryKind,
                        ignoreCase: false,
                        out var recoveryKind));
                    var reportLeg = new FileTransferLeg
                    {
                        LegId = $"test-runtime-unlock-lifecycle-{reportBridge.Direction.ToString().ToLowerInvariant()}",
                        Generation = reportBridge.TransferLegGeneration,
                        RouteSelection = coordinatorState.RouteSelection,
                        ProtocolVersion = reportBridge.ProtocolVersion,
                        LiveRouteEpochId = reportBridge.LiveRouteEpoch,
                        TransportEpochId = reportBridge.TransportEpoch,
                        BridgeRecoveryGeneration = reportBridge.BridgeRecoveryGeneration,
                        StartedUtc = DateTimeOffset.UtcNow,
                        State = FileTransferLegState.Active,
                        CanSendData = true,
                    };
                    coordinatorState = coordinatorState with
                    {
                        CurrentRuntimeOwner = recoveryAuthority.RecoveryLivenessLease.RuntimeOwner,
                        LastRuntimeOwnerGeneration = Math.Max(
                            coordinatorState.LastRuntimeOwnerGeneration,
                            reportBridge.RuntimeGeneration),
                        CurrentLeg = reportLeg,
                        LastTransferLegGeneration = Math.Max(
                            coordinatorState.LastTransferLegGeneration,
                            reportLeg.Generation),
                        CurrentBridgeRecoveryDecision = new BridgeRecoveryDecision(
                            true,
                            recoveryKind,
                            reportBridge.Reason,
                            reportBridge.BridgeDecisionGeneration,
                            coordinatorState.RouteSelection.Route,
                            reportBridge.ProtocolVersion,
                            reportBridge.LiveRouteEpoch,
                            reportBridge.RuntimeGeneration,
                            reportBridge.TerminalGeneration,
                            reportBridge.TransferLegGeneration,
                            reportBridge.TransportEpoch,
                            reportBridge.BridgeRecoveryGeneration,
                            recoveryAuthority.RecoveryLivenessLease.RuntimeOwner),
                        LastBridgeRecoveryDecisionGeneration = reportBridge.BridgeDecisionGeneration,
                        CurrentRecoveryLivenessLease = recoveryAuthority.RecoveryLivenessLease,
                        LastRetiredRecoveryLivenessLease = null,
                        LastRecoveryLivenessLeaseGeneration = Math.Max(
                            coordinatorState.LastRecoveryLivenessLeaseGeneration,
                            recoveryAuthority.RecoveryLivenessLease.LeaseGeneration),
                        RuntimeUnlockRecoveryLeaseClosureAvailable = false,
                    };
                }

                var lifecycleDecision =
                    FileTransferCoordinator.ObserveRuntimeUnlockRegularV4RecoveryLifecycle(
                        coordinatorState,
                        lastRegularV4Lifecycle,
                        args.Report);
                coordinatorState = lifecycleDecision.State;
                if (lifecycleDecision.Status ==
                    RuntimeUnlockRegularV4RecoveryLifecycleDecisionStatus.Accepted)
                {
                    lastRegularV4Lifecycle = args.Report;
                }

                Assert.True(
                    bridge.ObserveRuntimeUnlockRegularV4RecoveryLifecycleDecision(lifecycleDecision),
                    lifecycleDecision.Reason);
            };

            bridge.RuntimeUnlockRetryDispatchSettlementReported += (_, args) =>
            {
                Assert.NotNull(coordinatorState);
                if (terminalStateSelector?.Invoke(args.Report) == true)
                {
                    coordinatorState = coordinatorState! with
                    {
                        IsTerminal = true,
                        CurrentRuntimeUnlockRetryDispatchAuthority = null,
                    };
                }
                var settlementDecision = FileTransferCoordinator.ObserveRuntimeUnlockRetryDispatchSettlement(
                    coordinatorState!,
                    coordinatorContract,
                    lastSettlement,
                    args.Report);
                coordinatorState = settlementDecision.State;
                if (settlementDecision.Status == RuntimeUnlockRetryDispatchSettlementDecisionStatus.Accepted)
                {
                    lastSettlement = args.Report;
                    if (args.Report.Outcome is not RuntimeUnlockRetryDispatchSettlementOutcome.MissingDispatch)
                    {
                        coordinatorContract = null;
                    }
                }

                var observedDecision = settlementDecisionTransform?.Invoke(settlementDecision) ??
                    settlementDecision;
                var observed = bridge.ObserveRuntimeUnlockRetryDispatchSettlementDecision(observedDecision);
                if (settlementDecisionTransform is null)
                {
                    Assert.True(observed);
                }
            };

            bridge.RuntimeUnlockRegularV4RecoverySettlementReported += (_, args) =>
            {
                var settlement = args.Report.Settlement;
                if (coordinatorState is null)
                {
                    var retryState = typeof(NknSignalingTransport).GetField(
                        "runtimeUnlockRecoveryRetryState",
                        BindingFlags.Instance | BindingFlags.NonPublic)?.GetValue(transport);
                    var bootstrapPublication = retryState?.GetType()
                        .GetProperty("SourcePublicationAuthority")?
                        .GetValue(retryState) as FileTransferRoutePublicationAuthority ??
                        new FileTransferRoutePublicationAuthority(
                        settlement.SessionId,
                        settlement.TransferId,
                        settlement.Direction,
                        settlement.RouteToken,
                        settlement.ProtocolVersion,
                        settlement.LiveRouteEpoch,
                        settlement.RuntimeGeneration,
                        settlement.TerminalGeneration,
                        settlement.LegGeneration,
                        settlement.RoutePublicationGeneration,
                        settlement.RouteCommitGeneration,
                        FileTransferRouteResolver.RegularNknV4FastToken,
                        FileTransferProtocol.ProtocolVersionV4,
                        FileTransferTransportKind.RegularNkn,
                        FileTransferCoordinatorActionKind.RoutePublication.ToString(),
                        "test_handoff_bootstrap");
                    coordinatorState = CreateCoordinatorState(
                        new RuntimeUnlockRetryDispatchAuthorityRequest(
                            settlement.SessionId,
                            settlement.TransferId,
                            settlement.Direction,
                            bootstrapPublication,
                            RecoveryContractGeneration: 1,
                            RetiredOfferGeneration: 0,
                            DispatchAttemptGeneration: 1,
                            RetryReason: "runtime_unlock_offer_send_not_observed",
                            RecoveryReason: "regular_v4_recovery_consumed",
                            RegularV4LivenessGeneration: 0,
                            BridgeDecisionGeneration: settlement.BridgeDecisionGeneration),
                        prepareRetryRelease: false);
                }
                var owner = Assert.IsType<RuntimeOwnerToken>(coordinatorState!.CurrentRuntimeOwner);
                var leg = Assert.IsType<FileTransferLeg>(coordinatorState.CurrentLeg);
                var publication = Assert.IsType<RoutePublicationToken>(
                    coordinatorState.CurrentRoutePublicationToken);
                var repairDecision = new RepairReplayDecision(
                    Accepted: true,
                    RepairReplayKind.V4Repair,
                    settlement.DecisionReason,
                    settlement.DecisionGeneration,
                    coordinatorState.RouteSelection.Route,
                    coordinatorState.RouteSelection.ProtocolVersion,
                    settlement.LiveRouteEpoch,
                    settlement.RuntimeGeneration,
                    settlement.TerminalGeneration,
                    checked((int)settlement.LegGeneration),
                    settlement.TransportEpoch,
                    settlement.BridgeRecoveryGeneration,
                    owner,
                    settlement.AuthorityId,
                    PredecessorAuthorityId: null,
                    settlement.BridgeDecisionGeneration,
                    publication);
                coordinatorState = coordinatorState with
                {
                    CurrentRepairReplayDecision = repairDecision,
                    LastRepairReplayGeneration = repairDecision.RepairGeneration,
                    LastCoordinatorIssuedRegularV4RecoverySettlement = settlement,
                };
                var handoffDecision = FileTransferCoordinator.ObserveRuntimeUnlockRegularV4RecoverySettlement(
                    coordinatorState,
                    lastRegularV4Handoff,
                    args.Report);
                coordinatorState = handoffDecision.State;
                if (handoffDecision.Status ==
                    RuntimeUnlockRegularV4RecoverySettlementDecisionStatus.Accepted)
                {
                    lastRegularV4Handoff = args.Report;
                }

                var observed = bridge.ObserveRuntimeUnlockRegularV4RecoverySettlementDecision(handoffDecision);
                regularV4DecisionObserved?.Invoke(handoffDecision, observed);
                Assert.True(observed, handoffDecision.Reason);
            };
        }
        transport.RuntimeUnlockRetryDispatchAuthorityDecisionOverrideForTests = request =>
        {
            coordinatorState ??= CreateCoordinatorState(request);
            var selectedStatus = statusSelector?.Invoke(request) ??
                RuntimeUnlockRetryDispatchDecisionStatus.Granted;
            if (selectedStatus != RuntimeUnlockRetryDispatchDecisionStatus.Granted)
            {
                return new RuntimeUnlockRetryDispatchDecision(
                    selectedStatus,
                    selectedStatus == RuntimeUnlockRetryDispatchDecisionStatus.Held
                        ? "test_coordinator_held"
                        : "test_coordinator_rejected",
                    null)
                {
                    Request = request,
                    State = coordinatorState,
                };
            }

            RuntimeUnlockRetryReleaseKind releaseKind;
            FileTransferAuthorityId? releaseAuthorityId;
            int releaseGeneration;
            string releaseOutcome;
            if (coordinatorState.RouteSelection.Route == FileTransferRoute.RegularNknV4Fast)
            {
                if ((request.RegularV4LivenessGeneration > 0 ||
                     request.BridgeDecisionGeneration > 0) &&
                    coordinatorState.RuntimeUnlockRecoveryLeaseClosureAvailable &&
                    coordinatorState.LastRetiredRecoveryLivenessLease is { } closureLease)
                {
                    releaseKind = RuntimeUnlockRetryReleaseKind.ReceiveRecoveryLeaseClosure;
                    releaseAuthorityId = closureLease.AuthorityId;
                    releaseGeneration = closureLease.LeaseGeneration;
                    releaseOutcome = RecoveryLivenessLeaseState.Retired.ToString();
                }
                else if (coordinatorState.LastRuntimeUnlockRegularV4RecoverySettlement is
                    {
                        Disposition: RuntimeUnlockRegularV4RecoverySettlementDisposition.Consumed,
                    } handoff)
                {
                    releaseKind = RuntimeUnlockRetryReleaseKind.RegularV4RepairSettlement;
                    releaseAuthorityId = handoff.Settlement.AuthorityId;
                    releaseGeneration = handoff.Settlement.DecisionGeneration;
                    releaseOutcome = handoff.Settlement.Outcome.ToString();
                }
                else
                {
                    var lease = Assert.IsType<RecoveryLivenessLease>(
                        coordinatorState.LastRetiredRecoveryLivenessLease);
                    releaseKind = RuntimeUnlockRetryReleaseKind.ReceiveRecoveryLeaseClosure;
                    releaseAuthorityId = lease.AuthorityId;
                    releaseGeneration = lease.LeaseGeneration;
                    releaseOutcome = RecoveryLivenessLeaseState.Retired.ToString();
                }
            }
            else
            {
                var tailYield = Assert.IsType<FallbackTailYieldDecision>(
                    coordinatorState.LastFallbackTailYieldDecision);
                releaseKind = RuntimeUnlockRetryReleaseKind.FallbackPairedTailYield;
                releaseAuthorityId = tailYield.AuthorityId;
                releaseGeneration = tailYield.YieldGeneration;
                releaseOutcome = "PairedYieldGranted";
            }

            var decision = FileTransferCoordinator.AuthorizeRuntimeUnlockRetryDispatch(
                coordinatorState,
                request,
                coordinatorContract,
                releaseKind,
                releaseAuthorityId,
                releaseGeneration,
                releaseOutcome);
            coordinatorState = decision.State;
            if (decision.Granted)
            {
                coordinatorContract = decision.Contract;
                lastSettlement = decision.State.LastRuntimeUnlockRetryDispatchSettlement ?? lastSettlement;
            }
            else if (string.Equals(
                         decision.Reason,
                         "retry_dispatch_missing_successor_limit_exhausted",
                         StringComparison.Ordinal))
            {
                coordinatorContract = null;
            }

            return decisionTransform?.Invoke(decision) ?? decision;
        };
    }

    private static async Task<RuntimeUnlockRetryDispatchInstallFixture>
        CreateRuntimeUnlockRetryDispatchInstallFixtureAsync(string testName)
    {
        FakeNknClient.ResetNetwork();
        var suffix = $"{testName}-{Guid.NewGuid():N}";
        var options = NknTransportOptions.Load();
        var hostClient = new FakeNknClient($"host.{suffix}.address");
        var helperClient = new FakeNknClient($"helper.{suffix}.address");
        var host = new NknSignalingTransport(
            hostClient,
            options,
            new NknIdentity($"host-{suffix}-id", hostClient.Address),
            NknTunaAccelerationOptions.Disabled,
            accelerationLane: null);
        var helper = new NknSignalingTransport(
            helperClient,
            options,
            new NknIdentity($"helper-{suffix}-id", helperClient.Address));
        try
        {
            using var cts = new CancellationTokenSource(TimeSpan.FromSeconds(8));
            var sessionId = await ApproveNknSessionAsync(
                host,
                helper,
                cts.Token,
                InviteCapabilities.Chat | InviteCapabilities.FileTransfer);
            var transferId = $"transfer_{suffix}";
            var decisions = new List<RuntimeUnlockRetryDispatchDecision>();
            InstallRuntimeUnlockRetryDispatchCaptureCoordinatorForTests(host, decisions);
            _ = await host.OpenFileTransferDataSessionAsync(sessionId, transferId, cts.Token);
            TrackAuthorizedRegularV4RouteForTests(host, transferId);
            InvokePrivateMethod(
                host,
                "ArmRuntimeUnlockRetryAfterRecovery",
                0L,
                sessionId,
                "runtime_unlock_offer_send_not_observed",
                "regular_v4_repair_settled",
                false);

            Assert.Single(decisions);
            var state = GetPrivateField(host, "runtimeUnlockRecoveryRetryState");
            Assert.NotNull(state);
            return new RuntimeUnlockRetryDispatchInstallFixture(
                host,
                helper,
                Assert.IsAssignableFrom<IRuntimeUnlockRetryDispatchAuthorityBridge>(host),
                state!,
                decisions,
                sessionId,
                transferId);
        }
        catch
        {
            host.Dispose();
            helper.Dispose();
            FakeNknClient.ResetNetwork();
            throw;
        }
    }

    private static RuntimeUnlockRetryDispatchInstallReceipt
        CreateRuntimeUnlockRetryDispatchInstallReceipt(
            RuntimeUnlockRetryDispatchDecision decision,
            RuntimeUnlockRetryDispatchDecisionStageResult stage,
            long installGeneration,
            RuntimeUnlockRetryDispatchAuthority? authority = null)
    {
        var contract = Assert.IsType<RuntimeUnlockRetryDispatchContract>(decision.Contract);
        return new RuntimeUnlockRetryDispatchInstallReceipt(
            authority ?? contract.Authority,
            installGeneration)
        {
            Request = decision.Request,
            StageStatus = stage.Status,
            StageDisposition = stage.StageDisposition,
            StageCleared = stage.StageCleared,
            StagedUtcMs = stage.StagedUtcMs,
            StageExpiresUtcMs = stage.StageExpiresUtcMs,
        };
    }

    private static void InstallRuntimeUnlockRetryDispatchCaptureCoordinatorForTests(
        NknSignalingTransport transport,
        List<RuntimeUnlockRetryDispatchDecision> decisions)
        => InstallRuntimeUnlockRetryDispatchCoordinatorForTests(
            transport,
            decisionTransform: decision =>
            {
                decisions.Add(decision);
                return new RuntimeUnlockRetryDispatchDecision(
                    RuntimeUnlockRetryDispatchDecisionStatus.Held,
                    "test_phase2_stage_capture",
                    null)
                {
                    Request = decision.Request,
                    State = decision.State,
                };
            });

